from solution import re_order


def test_issue_example():
    """Move all zeroes to the end of the given array: issue example."""
    assert re_order([6, 0, 8, 2, 3, 0, 4, 0, 1]) == [6, 8, 2, 3, 4, 1, 0, 0, 0]  # 6 kept + 3 zeros = 9; 6+3=9


def test_issue_empty():
    """Move all zeroes to the end: empty array stays empty."""
    assert re_order([]) == []  # 0 kept + 0 zeros = 0; 0+0=0


def test_issue_no_zeroes():
    """Move all zeroes to the end: array with no zeroes is unchanged."""
    assert re_order([5, 1, 7]) == [5, 1, 7]  # 3 kept + 0 zeros = 3; 3+0=3


def test_issue_all_zeroes():
    """Move all zeroes to the end: array of only zeroes is unchanged."""
    assert re_order([0, 0, 0]) == [0, 0, 0]  # 0 kept + 3 zeros = 3; 0+3=3


def test_issue_single_zero():
    """Move all zeroes to the end: single zero stays single zero."""
    assert re_order([0]) == [0]  # 0 kept + 1 zero = 1; 0+1=1


def test_issue_single_nonzero():
    """Move all zeroes to the end: single non-zero stays unchanged."""
    assert re_order([42]) == [42]  # 1 kept + 0 zeros = 1; 1+0=1


def test_issue_leading_zeroes():
    """Move all zeroes to the end: leading zeroes move to end."""
    assert re_order([0, 0, 1, 2, 3]) == [1, 2, 3, 0, 0]  # 3 kept + 2 zeros = 5; 3+2=5


def test_issue_already_ordered():
    """Move all zeroes to the end: trailing zeroes stay at end."""
    assert re_order([1, 2, 3, 0, 0]) == [1, 2, 3, 0, 0]  # 3 kept + 2 zeros = 5; 3+2=5


def test_issue_preserves_order_with_consecutive_zeroes():
    """Move all zeroes to the end: non-zero order is preserved."""
    assert re_order([3, 0, 0, 1, 0, 2]) == [3, 1, 2, 0, 0, 0]  # 3 kept + 3 zeros = 6; 3+3=6


def test_issue_negative_and_small_values():
    """Move all zeroes to the end: values just above and below zero stay in order."""
    assert re_order([-1, 0, 1, 0, -2, 0, 2]) == [-1, 1, -2, 2, 0, 0, 0]  # 4 kept + 3 zeros = 7; 4+3=7


def test_contract_length_preserved():
    """Move all zeroes to the end must not add or remove elements."""
    assert len(re_order([4, 0, 5, 0, 6])) == 5  # 3 kept + 2 zeros = 5; 3+2=5


def test_contract_zero_count_preserved():
    """Move all zeroes to the end must preserve number of zeroes."""
    assert re_order([4, 0, 5, 0, 6]).count(0) == 2  # 5 total - 3 kept = 2 zeros; 5-3=2
